{
  "name": "Bajrang Juice Center POS",
  "description": "A high-speed, touch-optimized Point of Sale system for juice and thick shake stores, featuring instant billing, thermal receipt generation, and sales analytics.",
  "requestFramePermissions": [
    "camera"
  ]
}

export type Category = 'JUICES' | 'SHAKES' | 'SMOOTHIES' | 'ADD-ONS' | 'COMBOS';

export interface Product {
  id: string;
  name: string;
  price: number;
  category: Category;
  color: string;
}

export interface CartItem extends Product {
  quantity: number;
}

export type PaymentMethod = 'CASH' | 'UPI' | 'CARD';

export interface SaleRecord {
  id: string;
  billNo: string;
  items: CartItem[];
  subtotal: number;
  gst: number;
  total: number;
  paymentMethod: PaymentMethod;
  timestamp: number;
}

import { Product, Category } from './types';

export const CATEGORIES: Category[] = ['JUICES', 'SHAKES', 'SMOOTHIES', 'ADD-ONS', 'COMBOS'];

export const STORE_DETAILS = {
  name: 'BAJRANG JUICE CENTER',
  tagline: 'Fresh Juice & Thick Shakes',
  address: 'Jamnagar, Gujarat',
  gstin: '24XXXXX1234A1Z1',
  gstRate: 0.05
};

export const PRODUCTS: Product[] = [
  // Juices
  { id: 'j1', name: 'Mango Juice', price: 80, category: 'JUICES', color: 'bg-orange-100 border-orange-200 text-orange-800' },
  { id: 'j2', name: 'Orange Juice', price: 70, category: 'JUICES', color: 'bg-orange-50 border-orange-100 text-orange-700' },
  { id: 'j3', name: 'Watermelon Juice', price: 60, category: 'JUICES', color: 'bg-red-50 border-red-100 text-red-700' },
  { id: 'j4', name: 'Pineapple Juice', price: 70, category: 'JUICES', color: 'bg-yellow-50 border-yellow-100 text-yellow-700' },
  { id: 'j5', name: 'Mosambi Juice', price: 70, category: 'JUICES', color: 'bg-green-50 border-green-100 text-green-700' },

  // Shakes
  { id: 's1', name: 'Strawberry Shake', price: 120, category: 'SHAKES', color: 'bg-pink-100 border-pink-200 text-pink-800' },
  { id: 's2', name: 'Chocolate Shake', price: 130, category: 'SHAKES', color: 'bg-amber-100 border-amber-200 text-amber-900' },
  { id: 's3', name: 'Kaju Anjeer Shake', price: 160, category: 'SHAKES', color: 'bg-stone-100 border-stone-200 text-stone-800' },
  { id: 's4', name: 'Mango Shake', price: 110, category: 'SHAKES', color: 'bg-orange-100 border-orange-200 text-orange-800' },
  { id: 's5', name: 'Vanilla Shake', price: 100, category: 'SHAKES', color: 'bg-slate-50 border-slate-200 text-slate-800' },

  // Smoothies
  { id: 'sm1', name: 'Berry Blast', price: 150, category: 'SMOOTHIES', color: 'bg-purple-100 border-purple-200 text-purple-800' },
  { id: 'sm2', name: 'Green Detox', price: 140, category: 'SMOOTHIES', color: 'bg-emerald-100 border-emerald-200 text-emerald-800' },

  // Add-ons
  { id: 'a1', name: 'Extra Scoop Ice-cream', price: 30, category: 'ADD-ONS', color: 'bg-blue-50 border-blue-100 text-blue-700' },
  { id: 'a2', name: 'Dry Fruits', price: 20, category: 'ADD-ONS', color: 'bg-orange-50 border-orange-100 text-orange-700' },
  { id: 'a3', name: 'Chocolate Chips', price: 15, category: 'ADD-ONS', color: 'bg-brown-50 border-brown-100 text-brown-700' },

  // Combos
  { id: 'c1', name: 'Duo Pack (2 Juices)', price: 130, category: 'COMBOS', color: 'bg-indigo-100 border-indigo-200 text-indigo-800' },
];

import React, { useMemo } from 'react';
import { SaleRecord } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { Trash2, TrendingUp, Calendar, CreditCard, ChevronRight } from 'lucide-react';

interface HistoryProps {
  sales: SaleRecord[];
  onClear: () => void;
  onSelectSale: (sale: SaleRecord) => void;
}

const History: React.FC<HistoryProps> = ({ sales, onClear, onSelectSale }) => {
  const stats = useMemo(() => {
    const totalRevenue = sales.reduce((acc, s) => acc + s.total, 0);
    const count = sales.length;
    const methodCounts = sales.reduce((acc, s) => {
      acc[s.paymentMethod] = (acc[s.paymentMethod] || 0) + s.total;
      return acc;
    }, {} as Record<string, number>);

    return { totalRevenue, count, methodCounts };
  }, [sales]);

  const chartData = useMemo(() => {
    // Group by hour for today's visual
    const hours: Record<string, number> = {};
    sales.forEach(s => {
      const hour = new Date(s.timestamp).getHours();
      const label = `${hour}:00`;
      hours[label] = (hours[label] || 0) + s.total;
    });
    return Object.entries(hours).map(([name, total]) => ({ name, total }));
  }, [sales]);

  return (
    <div className="h-full flex flex-col p-6 overflow-y-auto">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-2xl font-bold text-gray-800">Sales Dashboard</h1>
          <p className="text-gray-500 text-sm">Real-time performance metrics</p>
        </div>
        <button 
          onClick={() => {
            if(confirm("Are you sure you want to clear all data?")) onClear();
          }}
          className="flex items-center gap-2 text-red-500 hover:bg-red-50 px-4 py-2 rounded-lg transition-colors"
        >
          <Trash2 size={18} />
          Clear Records
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
          <div className="flex items-center gap-4 mb-2">
            <div className="p-3 bg-green-100 text-green-600 rounded-xl">
              <TrendingUp size={24} />
            </div>
            <span className="text-sm font-medium text-gray-500 uppercase tracking-wider">Total Sales</span>
          </div>
          <div className="text-3xl font-bold text-gray-900">₹ {stats.totalRevenue.toLocaleString()}</div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
          <div className="flex items-center gap-4 mb-2">
            <div className="p-3 bg-blue-100 text-blue-600 rounded-xl">
              <Calendar size={24} />
            </div>
            <span className="text-sm font-medium text-gray-500 uppercase tracking-wider">Order Count</span>
          </div>
          <div className="text-3xl font-bold text-gray-900">{stats.count}</div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
          <div className="flex items-center gap-4 mb-2">
            <div className="p-3 bg-purple-100 text-purple-600 rounded-xl">
              <CreditCard size={24} />
            </div>
            <span className="text-sm font-medium text-gray-500 uppercase tracking-wider">UPI Share</span>
          </div>
          <div className="text-3xl font-bold text-gray-900">
            {stats.totalRevenue > 0 ? Math.round(((stats.methodCounts['UPI'] || 0) / stats.totalRevenue) * 100) : 0}%
          </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 mb-8 h-80">
        <h3 className="font-bold text-gray-800 mb-4">Sales by Hour</h3>
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={chartData}>
            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f0f0f0" />
            <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#999', fontSize: 12}} />
            <YAxis axisLine={false} tickLine={false} tick={{fill: '#999', fontSize: 12}} />
            <Tooltip 
              cursor={{fill: '#f8f8f8'}}
              contentStyle={{borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)'}}
            />
            <Bar dataKey="total" radius={[4, 4, 0, 0]}>
              {chartData.map((entry, index) => (
                <Cell key={`cell-${index}`} fill="#f59e0b" />
              ))}
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
        <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50/50">
          <h3 className="font-bold text-gray-800">Recent Transactions</h3>
        </div>
        <div className="divide-y divide-gray-100">
          {sales.length === 0 ? (
            <div className="p-12 text-center text-gray-400">No transactions recorded yet</div>
          ) : (
            sales.slice().reverse().map(sale => (
              <button 
                key={sale.id}
                onClick={() => onSelectSale(sale)}
                className="w-full flex items-center justify-between p-4 hover:bg-gray-50 transition-colors group"
              >
                <div className="flex items-center gap-4">
                  <div className="w-10 h-10 rounded-full bg-orange-50 flex items-center justify-center text-orange-600 font-bold">
                    #{sale.billNo.slice(-3)}
                  </div>
                  <div className="text-left">
                    <p className="font-semibold text-gray-900">₹ {sale.total.toFixed(2)}</p>
                    <p className="text-xs text-gray-500">
                      {new Date(sale.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })} • {sale.paymentMethod}
                    </p>
                  </div>
                </div>
                <div className="flex items-center gap-2 text-gray-400 group-hover:text-orange-500">
                   <span className="text-sm font-medium">{sale.items.length} items</span>
                   <ChevronRight size={18} />
                </div>
              </button>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

export default History;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { LayoutDashboard, ShoppingCart, History as HistoryIcon, User, Plus, Minus, X, Check, Printer, Smartphone, CreditCard, Banknote } from 'lucide-react';
import { Product, CartItem, SaleRecord, Category, PaymentMethod } from './types';
import { PRODUCTS, CATEGORIES, STORE_DETAILS } from './constants';
import Receipt from './components/Receipt';
import History from './components/History';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'POS' | 'HISTORY'>('POS');
  const [activeCategory, setActiveCategory] = useState<Category>('JUICES');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [sales, setSales] = useState<SaleRecord[]>([]);
  const [showCheckout, setShowCheckout] = useState(false);
  const [currentSale, setCurrentSale] = useState<SaleRecord | null>(null);

  // Load from storage on mount
  useEffect(() => {
    const savedSales = localStorage.getItem('bjc_sales_history');
    if (savedSales) {
      setSales(JSON.parse(savedSales));
    }
  }, []);

  // Save to storage
  const saveSales = (newSales: SaleRecord[]) => {
    setSales(newSales);
    localStorage.setItem('bjc_sales_history', JSON.stringify(newSales));
  };

  const addToCart = (product: Product) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (productId: string) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === productId);
      if (existing && existing.quantity > 1) {
        return prev.map(item => item.id === productId ? { ...item, quantity: item.quantity - 1 } : item);
      }
      return prev.filter(item => item.id !== productId);
    });
  };

  const clearCart = () => setCart([]);

  const subtotal = useMemo(() => cart.reduce((acc, item) => acc + (item.price * item.quantity), 0), [cart]);
  const gst = useMemo(() => subtotal * STORE_DETAILS.gstRate, [subtotal]);
  const total = useMemo(() => subtotal + gst, [subtotal, gst]);

  const handleCheckout = (method: PaymentMethod) => {
    const billNo = (1000 + sales.length + 1).toString();
    const newSale: SaleRecord = {
      id: Date.now().toString(),
      billNo,
      items: [...cart],
      subtotal,
      gst,
      total,
      paymentMethod: method,
      timestamp: Date.now()
    };

    const updatedSales = [...sales, newSale];
    saveSales(updatedSales);
    setCurrentSale(newSale);
    setShowCheckout(false);
    clearCart();
    // In a real device, this would trigger Bluetooth/USB printing
    setTimeout(() => {
        window.print();
    }, 500);
  };

  const renderPOS = () => (
    <div className="flex flex-col lg:flex-row h-full overflow-hidden">
      {/* Products Side */}
      <div className="flex-1 flex flex-col h-full bg-gray-50 border-r border-gray-200">
        {/* Categories Scroller */}
        <div className="bg-white border-b border-gray-200 px-4 py-3">
          <div className="flex gap-2 overflow-x-auto hide-scrollbar">
            {CATEGORIES.map(cat => (
              <button
                key={cat}
                onClick={() => setActiveCategory(cat)}
                className={`px-6 py-2 rounded-xl text-sm font-semibold whitespace-nowrap transition-all ${
                  activeCategory === cat 
                    ? 'bg-orange-500 text-white shadow-lg shadow-orange-200' 
                    : 'bg-gray-100 text-gray-500 hover:bg-gray-200'
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>

        {/* Product Grid */}
        <div className="flex-1 overflow-y-auto p-4 md:p-6">
          <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 gap-4">
            {PRODUCTS.filter(p => p.category === activeCategory).map(product => {
              const inCart = cart.find(i => i.id === product.id);
              return (
                <button
                  key={product.id}
                  onClick={() => addToCart(product)}
                  className={`relative flex flex-col items-start p-4 rounded-2xl border-2 transition-all active:scale-95 text-left h-36 ${product.color} shadow-sm hover:shadow-md`}
                >
                  <span className="font-bold text-lg leading-tight mb-1">{product.name}</span>
                  <span className="font-semibold text-sm opacity-80 mt-auto">₹ {product.price}</span>

                  {inCart && (
                    <div className="absolute -top-2 -right-2 bg-orange-600 text-white w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm shadow-md border-2 border-white">
                      {inCart.quantity}
                    </div>
                  )}

                  <div className="absolute bottom-4 right-4 bg-white/40 p-1 rounded-full">
                    <Plus size={20} />
                  </div>
                </button>
              );
            })}
          </div>
        </div>
      </div>

      {/* Cart Side */}
      <div className="w-full lg:w-96 bg-white flex flex-col h-full shadow-2xl z-10">
        <div className="p-6 border-b border-gray-100 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <ShoppingCart className="text-orange-500" />
            <h2 className="text-xl font-bold text-gray-800">Your Cart</h2>
          </div>
          {cart.length > 0 && (
            <button onClick={clearCart} className="text-gray-400 hover:text-red-500">
              <X size={20} />
            </button>
          )}
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-4">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-gray-400 gap-4">
              <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center">
                 <ShoppingCart size={40} />
              </div>
              <p className="font-medium">No items in cart</p>
            </div>
          ) : (
            cart.map(item => (
              <div key={item.id} className="flex items-center justify-between p-3 bg-gray-50 rounded-xl">
                <div className="flex-1">
                  <h4 className="font-semibold text-gray-800 text-sm">{item.name}</h4>
                  <p className="text-xs text-gray-500">₹ {item.price} each</p>
                </div>
                <div className="flex items-center gap-3">
                  <button onClick={() => removeFromCart(item.id)} className="p-1 bg-white border border-gray-200 rounded-lg text-gray-600 hover:bg-orange-50 hover:text-orange-600">
                    <Minus size={16} />
                  </button>
                  <span className="font-bold text-gray-800 w-4 text-center">{item.quantity}</span>
                  <button onClick={() => addToCart(item)} className="p-1 bg-white border border-gray-200 rounded-lg text-gray-600 hover:bg-orange-50 hover:text-orange-600">
                    <Plus size={16} />
                  </button>
                </div>
                <div className="w-20 text-right font-bold text-gray-800 ml-2">
                  ₹ {item.price * item.quantity}
                </div>
              </div>
            ))
          )}
        </div>

        {/* Totals Section */}
        <div className="p-6 bg-gray-50/50 border-t border-gray-100">
          <div className="space-y-2 mb-6 text-sm font-medium">
            <div className="flex justify-between text-gray-500">
              <span>Subtotal</span>
              <span>₹ {subtotal.toFixed(2)}</span>
            </div>
            <div className="flex justify-between text-gray-500">
              <span>GST (5%)</span>
              <span>₹ {gst.toFixed(2)}</span>
            </div>
            <div className="flex justify-between text-xl font-bold text-gray-900 pt-2 border-t border-gray-200">
              <span>Total</span>
              <span className="text-orange-600">₹ {total.toFixed(2)}</span>
            </div>
          </div>

          <button
            disabled={cart.length === 0}
            onClick={() => setShowCheckout(true)}
            className="w-full bg-orange-500 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-3 shadow-lg shadow-orange-100 disabled:opacity-50 disabled:shadow-none hover:bg-orange-600 active:scale-[0.98] transition-all"
          >
            CHECKOUT NOW
            <ChevronRight size={20} />
          </button>
        </div>
      </div>
    </div>
  );

  return (
    <div className="flex h-screen w-full bg-gray-100">
      {/* Sidebar Nav */}
      <div className="hidden sm:flex flex-col w-20 bg-gray-900 py-8 items-center gap-10">
        <div className="w-12 h-12 bg-orange-500 rounded-2xl flex items-center justify-center shadow-lg shadow-orange-900/40">
           <img src="https://picsum.photos/40/40" className="rounded-xl opacity-80" alt="logo" />
        </div>

        <nav className="flex flex-col gap-6">
          <button 
            onClick={() => setActiveTab('POS')}
            className={`p-3 rounded-2xl transition-all ${activeTab === 'POS' ? 'bg-orange-500 text-white shadow-lg' : 'text-gray-500 hover:bg-gray-800'}`}
          >
            <ShoppingCart size={24} />
          </button>
          <button 
            onClick={() => setActiveTab('HISTORY')}
            className={`p-3 rounded-2xl transition-all ${activeTab === 'HISTORY' ? 'bg-orange-500 text-white shadow-lg' : 'text-gray-500 hover:bg-gray-800'}`}
          >
            <HistoryIcon size={24} />
          </button>
        </nav>

        <div className="mt-auto flex flex-col gap-6">
           <button className="text-gray-500 hover:text-white transition-colors">
              <LayoutDashboard size={24} />
           </button>
           <button className="text-gray-500 hover:text-white transition-colors">
              <User size={24} />
           </button>
        </div>
      </div>

      {/* Main Content Area */}
      <main className="flex-1 h-full overflow-hidden relative">
        {activeTab === 'POS' ? renderPOS() : (
          <History 
            sales={sales} 
            onClear={() => saveSales([])} 
            onSelectSale={(s) => { setCurrentSale(s); }} 
          />
        )}
      </main>

      {/* Checkout Modal */}
      {showCheckout && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-[32px] w-full max-w-md overflow-hidden shadow-2xl">
            <div className="p-8 text-center border-b border-gray-50">
              <p className="text-gray-500 font-medium mb-1">Total Payable</p>
              <h2 className="text-4xl font-black text-gray-900">₹ {total.toFixed(2)}</h2>
            </div>

            <div className="p-8 space-y-4">
              <p className="text-sm font-bold text-gray-400 uppercase tracking-widest text-center">Select Payment Mode</p>
              <div className="grid grid-cols-1 gap-4">
                <button 
                  onClick={() => handleCheckout('UPI')}
                  className="flex items-center justify-between p-5 rounded-2xl border-2 border-gray-100 hover:border-orange-500 hover:bg-orange-50 transition-all group"
                >
                  <div className="flex items-center gap-4">
                    <div className="p-3 bg-blue-100 text-blue-600 rounded-xl group-hover:bg-blue-600 group-hover:text-white transition-colors">
                      <Smartphone size={24} />
                    </div>
                    <span className="font-bold text-gray-800">UPI Payment</span>
                  </div>
                  <ChevronRight className="text-gray-300" />
                </button>

                <button 
                  onClick={() => handleCheckout('CASH')}
                  className="flex items-center justify-between p-5 rounded-2xl border-2 border-gray-100 hover:border-orange-500 hover:bg-orange-50 transition-all group"
                >
                  <div className="flex items-center gap-4">
                    <div className="p-3 bg-green-100 text-green-600 rounded-xl group-hover:bg-green-600 group-hover:text-white transition-colors">
                      <Banknote size={24} />
                    </div>
                    <span className="font-bold text-gray-800">Cash Payment</span>
                  </div>
                  <ChevronRight className="text-gray-300" />
                </button>

                <button 
                  onClick={() => handleCheckout('CARD')}
                  className="flex items-center justify-between p-5 rounded-2xl border-2 border-gray-100 hover:border-orange-500 hover:bg-orange-50 transition-all group"
                >
                  <div className="flex items-center gap-4">
                    <div className="p-3 bg-purple-100 text-purple-600 rounded-xl group-hover:bg-purple-600 group-hover:text-white transition-colors">
                      <CreditCard size={24} />
                    </div>
                    <span className="font-bold text-gray-800">Card Payment</span>
                  </div>
                  <ChevronRight className="text-gray-300" />
                </button>
              </div>

              <button 
                onClick={() => setShowCheckout(false)}
                className="w-full text-center text-gray-400 font-semibold py-4 hover:text-gray-600"
              >
                Back to Billing
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Sale Details Modal / Last Receipt */}
      {currentSale && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[60] flex items-center justify-center p-4">
          <div className="relative max-h-[90vh] overflow-y-auto">
             <button 
                onClick={() => setCurrentSale(null)}
                className="absolute -top-12 right-0 text-white bg-white/20 p-2 rounded-full hover:bg-white/30"
              >
                <X size={24} />
              </button>
              <div className="bg-white rounded-xl shadow-2xl p-2">
                <Receipt sale={currentSale} />
              </div>
              <div className="mt-6 flex gap-4 no-print">
                 <button 
                  onClick={() => window.print()}
                  className="flex-1 bg-white text-gray-900 font-bold py-4 rounded-xl flex items-center justify-center gap-2"
                 >
                   <Printer size={20} />
                   PRINT RECEIPT
                 </button>
                 <button 
                  onClick={() => setCurrentSale(null)}
                  className="flex-1 bg-orange-500 text-white font-bold py-4 rounded-xl flex items-center justify-center gap-2"
                 >
                   <Check size={20} />
                   DONE
                 </button>
              </div>
          </div>
        </div>
      )}

      {/* Hidden Print Area */}
      <div className="hidden">
        {currentSale && <Receipt sale={currentSale} id="receipt-print-area" />}
      </div>
    </div>
  );
};

// Simple helpers used in App.tsx
const ChevronRight = ({ size = 24, className = "" }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}>
