      onUpdateProducts(updated);
      setIsEditing(null);
    } else {
      const newProduct: Product = {
        ...formData as Product,
        id: Date.now().toString(),
        color: formData.color || 'bg-gray-50 border-gray-200 text-gray-800'
      };
      onUpdateProducts([...products, newProduct]);
      setShowAddForm(false);
